 public static boolean combat(Object n){if(!military(n))return false;try{if(Downed20.down(n)||Social.pause(n))return true;CalmBrain.State st=CalmBrain.state(n);Object target=st.target;if(!CalmBrain.alive(target))return Radio22.search(n,st);if(TeamBrain.gunTick(n))return true;if(!CalmBrain.visible(n,target))return true;CalmBrain.face(n,target);long now=Social.time(n);if(now<st.nextPath)return true;double dx=Social.num(c(target,"getX"))-Social.num(c(n,"getX")),dz=Social.num(c(target,"getZ"))-Social.num(c(n,"getZ")),distance=Math.max(.01,Math.hypot(dx,dz));double x=Social.num(c(n,"getX")),y=Social.num(c(n,"getY")),z=Social.num(c(n,"getZ"));if(distance>19)CalmBrain.path(n,st,now,Social.num(c(target,"getX")),Social.num(c(target,"getY")),Social.num(c(target,"getZ")),1.1);else if(distance<7)CalmBrain.path(n,st,now,x-dx/distance*4,y,z-dz/distance*4,1.1);else{double side=((Social.uuid(n).getLeastSignificantBits()&1)==0?1:-1);CalmBrain.path(n,st,now,x-dz/distance*side*2,y,z+dx/distance*side*2,1.0);CalmBrain.crouch(n,Reflect.yes(c(c(n,"getNavigation"),"isDone")));}st.nextPath=now+20;return true;}catch(Exception e){CalmBrain.error("military22 combat",e);return true;}}
